import urllib.request,json,time,subprocess
rid='run_mvaxg8be_1099f77b3b'
obs=[]
for i in range(5):
 try:
  with urllib.request.urlopen('http://127.0.0.1:8787/v1/status/'+rid,timeout=5) as r:o=json.load(r)
  d=o.get('durable') or {};c=d.get('workflow_cursor') or {}
  sample={'i':i+1,'status':d.get('job_status'),'generation':d.get('generation'),'step':c.get('step_id'),'phase':c.get('step_phase')}
  if not obs or sample['status']!=obs[-1]['status'] or sample['generation']!=obs[-1]['generation'] or sample['step']!=obs[-1]['step'] or sample['phase']!=obs[-1]['phase']:obs.append(sample)
  if sample['status'] in ('BLOCKED','DONE','FAILED','CANCELLED'):break
 except Exception as e:obs.append({'i':i+1,'error':type(e).__name__})
 if i<4:time.sleep(11)
if not obs:raise SystemExit('EMPTY_OBSERVATION')
body='DEBUGAI_REAL_E2E_FOLLOWUP\n'+json.dumps({'run_id':rid,'observations':obs},ensure_ascii=False,indent=2)
p=subprocess.run(['gh','api','-X','POST','repos/seigo-gace/debug-ai/issues/41/comments','-f','body='+body],capture_output=True,text=True,timeout=28)
if p.returncode:raise SystemExit('FOLLOWUP_WRITE_FAILED')
print('E2E_FOLLOWUP_COMMENT='+json.loads(p.stdout)['html_url'])
